import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { visionScannersObservationsList } from '../generated/api'
import type { ReplayObservationApi } from '../generated/api.schemas'

export interface WatchFeedGroupLogicProps {
    /** The card's observation. The backend resolves its duplicate group from it. */
    observationId: string
    scannerId: string
    dateFrom: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface watchFeedGroupLogicValues {
    currentTeamId: number | null // teamLogic
    expanded: boolean
    members: ReplayObservationApi[] | null
    membersLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface watchFeedGroupLogicActions {
    toggleExpanded: () => { value: true }
    loadMembers: (_: void) => void
    loadMembersFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadMembersSuccess: (
        members: ReplayObservationApi[] | null,
        payload?: any
    ) => {
        members: ReplayObservationApi[] | null
        payload?: any
    }
}

export type watchFeedGroupLogicType = MakeLogicType<
    watchFeedGroupLogicValues,
    watchFeedGroupLogicActions,
    WatchFeedGroupLogicProps
>

/** How many of the group's other sessions the card lists before it links to the full list. */
export const WATCH_GROUP_PREVIEW_SIZE = 5

/** The other sessions in a feed card's duplicate group, loaded the first time the card expands. */
export const watchFeedGroupLogic = kea<watchFeedGroupLogicType>([
    path((key) => ['products', 'replay_vision', 'frontend', 'replay_scanners', 'watchFeedGroupLogic', key]),
    props({} as WatchFeedGroupLogicProps),
    key((props) => props.observationId),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        toggleExpanded: true,
    }),
    reducers({
        expanded: [false, { toggleExpanded: (expanded) => !expanded }],
    }),
    loaders(({ props, values }) => ({
        members: [
            null as ReplayObservationApi[] | null,
            {
                loadMembers: async (): Promise<ReplayObservationApi[] | null> => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    const page = await visionScannersObservationsList(String(values.currentTeamId), props.scannerId, {
                        watch_group: props.observationId,
                        date_from: props.dateFrom,
                        status: 'succeeded',
                        limit: WATCH_GROUP_PREVIEW_SIZE + 1,
                    })
                    // The card's own session already sits above the list.
                    return page.results
                        .filter((member) => member.id !== props.observationId)
                        .slice(0, WATCH_GROUP_PREVIEW_SIZE)
                },
            },
        ],
    })),
    listeners(({ actions, values }) => ({
        toggleExpanded: () => {
            if (values.expanded && values.members === null && !values.membersLoading) {
                actions.loadMembers()
            }
        },
    })),
])
